const inFlight = [1, 2, 3, 4, 5];
function abruptShutdown(reqs) {
  // process exits immediately: nothing in flight gets to finish
  return reqs.length;
}
function gracefulShutdown(reqs) {
  // stop accepting new work, then drain: each in-flight request finishes
  let finished = 0;
  for (const _ of reqs) finished++;
  return reqs.length - finished;
}
console.log('abrupt dropped=' + abruptShutdown(inFlight));
console.log('graceful dropped=' + gracefulShutdown(inFlight));
